add_action( 'woocommerce_review_order_before_payment', 'perfectpixel_radio_fee_options' );
add_action( 'woocommerce_checkout_update_order_review', 'perfectpixel_radio_fee_store' );
add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_radio_fee_apply' );
add_action( 'woocommerce_checkout_order_processed', 'perfectpixel_radio_fee_reset' );

/**
 * Option key => [ label, fee amount ].
 */
function perfectpixel_radio_fee_choices() {
	return array(
		'none'    => array( 'Χωρίς συσκευασία', 0 ),
		'gift'    => array( 'Συσκευασία δώρου', 3 ),
		'premium' => array( 'Premium συσκευασία', 6 ),
	);
}

function perfectpixel_radio_fee_options() {
	$chosen = WC()->session ? WC()->session->get( 'perfectpixel_radio_fee', 'none' ) : 'none';
	echo '<div class="perfectpixel-radio-fee" style="margin:0 0 1em"><h3>' . esc_html( '{{radio_fee_title}}' ) . '</h3>';
	foreach ( perfectpixel_radio_fee_choices() as $key => $choice ) {
		printf(
			'<p style="margin:.25em 0"><label><input type="radio" name="perfectpixel_radio_fee" value="%1$s" %2$s> %3$s%4$s</label></p>',
			esc_attr( $key ),
			checked( $chosen, $key, false ),
			esc_html( $choice[0] ),
			$choice[1] > 0 ? ' (+' . wp_kses_post( wc_price( $choice[1] ) ) . ')' : ''
		);
	}
	echo '</div>';
	?>
	<script>
	jQuery( function ( $ ) {
		$( document.body ).off( 'change.perfectpixel' ).on( 'change.perfectpixel', 'input[name="perfectpixel_radio_fee"]', function () {
			$( document.body ).trigger( 'update_checkout' );
		} );
	} );
	</script>
	<?php
}

function perfectpixel_radio_fee_store( $posted ) {
	parse_str( (string) $posted, $data );
	if ( isset( $data['perfectpixel_radio_fee'] ) && array_key_exists( $data['perfectpixel_radio_fee'], perfectpixel_radio_fee_choices() ) ) {
		WC()->session->set( 'perfectpixel_radio_fee', $data['perfectpixel_radio_fee'] );
	}
}

function perfectpixel_radio_fee_apply( $cart ) {
	if ( is_admin() && ! defined( 'DOING_AJAX' ) ) {
		return;
	}
	$key     = WC()->session ? WC()->session->get( 'perfectpixel_radio_fee', 'none' ) : 'none';
	$choices = perfectpixel_radio_fee_choices();
	if ( isset( $choices[ $key ] ) && $choices[ $key ][1] > 0 ) {
		$cart->add_fee( $choices[ $key ][0], $choices[ $key ][1], true );
	}
}

function perfectpixel_radio_fee_reset() {
	if ( WC()->session ) {
		WC()->session->set( 'perfectpixel_radio_fee', 'none' );
	}
}
